def split_at_offset(groups, offset, normalize=False):
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        raise ValueError('offset must be a nonnegative integer')
    if not isinstance(normalize, bool):
        raise ValueError('normalize must be a boolean')
    try:
        iterator = iter(groups)
    except TypeError as exc:
        raise ValueError('groups must be iterable') from exc

    validated = []
    for group in iterator:
        if not isinstance(group, (tuple, list)) or len(group) != 2:
            raise ValueError('each group must be a character/count pair')
        ch, count = group
        if not isinstance(ch, str) or len(ch) != 1:
            raise ValueError('character must be one Unicode code point')
        if isinstance(count, bool) or not isinstance(count, int) or count <= 0:
            raise ValueError('count must be a positive integer')
        validated.append((ch, count))

    if offset > sum(count for _, count in validated):
        raise ValueError('offset is outside the encoding')

    left, right = [], []
    remaining = offset

    def append(side, ch, count):
        if count == 0:
            return
        if normalize and side and side[-1][0] == ch:
            side[-1] = (ch, side[-1][1] + count)
        else:
            side.append((ch, count))

    for ch, count in validated:
        taken = min(remaining, count)
        append(left, ch, taken)
        append(right, ch, count - taken)
        remaining -= taken
    return left, right


